326	    /**
327	     * Loads the owner with the given id and, when it exists, produces the response through
328	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
329	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
330	     * the not-found response are written in exactly one place rather than copied into each method.
331	     *
332	     * @param ownerId the id of the owner to load
333	     * @param action builds the response for an existing owner
334	     * @param <T> the response body type
335	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
336	     */
337	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
338	        Owner owner = this.clinicService.findOwnerById(ownerId);
339	        if (owner == null) {
340	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
341	        }
342	        return action.apply(owner);
343	    }
344	
345	    /**
346	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
347	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag,
348	     * the {@code identityKey} and the {@code possibleDuplicate} pair), and re-applies the owner's
349	     * {@code membershipLevel} through the controller ({@link #membershipLevel(Owner)}). Both the
350	     * create endpoint and the single-owner read endpoint return their owner through this method, so
351	     * an owner is decorated identically on either path and each derived field is computed in exactly
352	     * one place.
353	     *
354	     * @param owner the persisted owner to represent
355	     * @return the owner DTO with its derived read-only fields populated
356	     */
357	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
358	        owner.setHouseholdSize(householdSize(owner));
359	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
360	        ownerDto.setMembershipLevel(membershipLevel(owner));
361	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
362	        ownerDto.setIdentityKey(identityKey(owner));
363	        Integer possibleDuplicateOf = owner.getPossibleDuplicateOf();
364	        ownerDto.setPossibleDuplicate(possibleDuplicateOf != null);
365	        ownerDto.setPossibleDuplicateOf(possibleDuplicateOf);
366	        return ownerDto;
367	    }
368	
369	    /**
370	     * The {@code membershipLevel} reported for a single owner. Starts from the owner-local derivation
371	     * in {@link OwnerMapper#membershipLevel(Owner)} (the level from the owner's own membership points),
372	     * routed through the controller so the create audit log and the single-owner response agree on one
373	     * value. Unlike the mapper - which sees only the owner - the controller can reach the rest of the
374	     * clinic, so this is the single place a reported membership level is shaped by cross-owner context.
375	     *
376	     * <p>Household ceiling: the reported level is capped at one above the current maximum
377	     * {@linkplain #householdMemberLevel(Owner) level} among the owner's <em>existing</em>
378	     * {@link #householdMembers(Owner) household members} (those sharing its {@code householdId}, other
379	     * than the owner itself). With no existing household member no cap applies and the owner-local level
380	     * is reported unchanged. The cap uses each member's own owner-local level (not their reported,
381	     * capped level), so it depends only on the members' own points and cannot recurse.
382	     *
383	     * @param owner the owner whose reported membership level is wanted
384	     * @return the owner's membership level, capped at one above its household maximum
385	     */
386	    private Integer membershipLevel(Owner owner) {
387	        int ownLevel = ownerMapper.membershipLevel(owner);
388	        java.util.OptionalInt maxHouseholdLevel = householdMembers(owner).stream()
389	            .filter(member -> !java.util.Objects.equals(member.getId(), owner.getId()))
390	            .mapToInt(this::householdMemberLevel)
391	            .max();
392	        if (maxHouseholdLevel.isEmpty()) {
393	            return ownLevel;
394	        }
395	        return Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1);
396	    }
397	
398	    /**
399	     * The owner-local membership level of a household member, used only as an input to the household
400	     * ceiling in {@link #membershipLevel(Owner)}. The member's {@link Owner#getHouseholdSize()
401	     * household size} is set from its household before the level is derived, so the member's household
402	     * factor is accounted for exactly as it is when the member is reported on its own; the level itself
403	     * comes from the owner-local {@link OwnerMapper#membershipLevel(Owner)}.
404	     *
405	     * @param member an existing member of an owner's household
406	     * @return the member's owner-local membership level
407	     */
408	    private int householdMemberLevel(Owner member) {
409	        member.setHouseholdSize(householdSize(member));
410	        return ownerMapper.membershipLevel(member);
411	    }
412	
413	    /**
414	     * Canonicalizes the submitted address in place before it is validated, stored and returned, so
415	     * every later step - the required-field check, the persisted value and the response - sees the
416	     * single normalized form produced by {@link AddressNormalizer#normalize(String)} (see that method
417	     * for the trim/collapse/upper-case/abbreviation rules). Normalizing once here, at the head of the
418	     * create flow, keeps address canonicalization in exactly one place rather than spread across the
419	     * steps that read the address.
420	     *
421	     * <p>An address may be supplied either as the structured {@code addressLine1} (with an optional
422	     * {@code addressLine2}) or as the single flat {@code address}, the latter kept for backward
423	     * compatibility. Whichever address fields are supplied are normalized, and the structured fields
424	     * are preferred when present: the flat {@code address} returned is composed as the normalized
425	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
426	     * {@code addressLine2} is present; only when no {@code addressLine1} is supplied does the flat
427	     * {@code address} retain its own normalized value.
428	     *
429	     * @param ownerFieldsDto the submitted owner fields, whose address fields are replaced with their normalized form
430	     */
431	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
432	        String addressLine1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
433	        String addressLine2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
434	        String flatAddress = addressNormalizer.normalize(ownerFieldsDto.getAddress());
435	        ownerFieldsDto.setAddressLine1(addressLine1);
436	        ownerFieldsDto.setAddressLine2(addressLine2);
437	        if (addressLine1 != null && !addressLine1.isBlank()) {
438	            String composed = addressLine2 != null && !addressLine2.isBlank()
439	                ? addressLine1 + " " + addressLine2
440	                : addressLine1;
441	            ownerFieldsDto.setAddress(composed);
442	        } else {
443	            ownerFieldsDto.setAddress(flatAddress);
444	        }
445	    }
446	
447	    /**
448	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
449	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
450	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
451	     * blank (e.g. {@code "   "}). The offending field names are reported through an
452	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
453	     * as a 400 response carrying an {@code errors} array of field names.
454	     *
455	     * @param ownerFieldsDto the submitted owner fields
456	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
457	     */
458	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
459	        List<String> blankFields = new ArrayList<>();
460	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
461	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
462	        addRequiredAddress(blankFields, ownerFieldsDto);
463	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
464	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
465	        if (!blankFields.isEmpty()) {
466	            throw new InvalidOwnerFieldsException(blankFields);
467	        }
468	    }
469	
470	    private void addIfBlank(List<String> blankFields, String field, String value) {
471	        if (value != null && value.isBlank()) {
472	            blankFields.add(field);
473	        }
474	    }
475	
476	    /**
477	     * Records the address requirement's offending field name(s) into {@code blankFields}. An owner
478	     * must supply an address in EITHER accepted form: the structured {@code addressLine1} or the flat
479	     * {@code address} (kept for backward compatibility). The requirement is satisfied when at least one
480	     * of those is present and non-blank; only when both are missing or blank is {@code address} reported
481	     * as the offending field. Holding the "an owner must have an address" rule in its own method - rather
482	     * than a bare entry in the field list - gives it one place to live as the accepted address forms grow.
483	     *
484	     * @param blankFields the accumulating list of blank required-field names
485	     * @param ownerFieldsDto the submitted owner fields
486	     */
487	    private void addRequiredAddress(List<String> blankFields, OwnerFieldsDto ownerFieldsDto) {
488	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
489	            blankFields.add("address");
490	        }
491	    }
492	
493	    private boolean isBlank(String value) {
494	        return value == null || value.isBlank();
495	    }
496	
497	    /**
498	     * Rejects an owner whose {@code email} domain is on the disposable-domain blocklist
499	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is validated
500	     * only when present, so an owner created without one is accepted unchanged; syntactic validity is
501	     * already enforced by Bean Validation's {@code @Email} constraint on {@link OwnerFieldsDto}, so
502	     * this only rejects an otherwise well-formed address that uses a throwaway provider (see
