542	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
543	     * the {@code customerCode}.
544	     */
545	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
546	
547	    /**
548	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
549	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
550	     * its {@code postcode} (falling back to its {@code city}) through the shared
551	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
552	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
553	     * (e.g. {@code 'NSW-1A2B3C4D'}). When this base code collides with an existing owner's
554	     * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that
555	     * makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}), so distinct owners always receive
556	     * distinct customer codes.
557	     *
558	     * @param owner the owner being created, with its telephone already normalized
559	     * @return the formatted, de-duplicated customer code
560	     */
561	    private String customerCode(Owner owner) {
562	        String region = Region.code(owner.getPostcode(), owner.getCity());
563	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
564	        String base = region + "-" + hash8;
565	        return deduplicateCustomerCode(base);
566	    }
