568	    /**
569	     * Ensures the given base {@code customerCode} does not collide with an existing owner's
570	     * {@code customerCode}. When no existing owner carries the base code it is returned unchanged;
571	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code
572	     * held by no existing owner.
573	     *
574	     * @param base the computed base customer code, formatted {@code '<REGION>-<HASH8>'}
575	     * @return the base code, or a {@code '<base>-<n>'} variant that is unique among existing owners
576	     */
577	    private String deduplicateCustomerCode(String base) {
578	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
579	            .map(Owner::getCustomerCode)
580	            .filter(java.util.Objects::nonNull)
581	            .collect(java.util.stream.Collectors.toSet());
582	        if (!existing.contains(base)) {
583	            return base;
584	        }
585	        int n = 2;
586	        while (existing.contains(base + "-" + n)) {
587	            n++;
588	        }
589	        return base + "-" + n;
590	    }
