697	    /**
698	     * Adjusts a date so it falls on a business day, rolling forward off weekends and public
699	     * holidays. A Saturday, Sunday or {@link #PUBLIC_HOLIDAYS listed public holiday} is rolled
700	     * forward one day at a time until the first non-holiday weekday is reached; any other weekday is
701	     * returned unchanged. Applied to the effective registration date so that a weekend or holiday
702	     * value - whether supplied in the request or defaulted to the server date - is stored as the
703	     * next business day, and every value derived from the registration date (such as the membership
704	     * number's year segment and the daily create-limit bucket) uses the adjusted business day.
705	     *
706	     * @param date the effective registration date
707	     * @return the same date when it is a non-holiday weekday, otherwise the next business day
708	     */
709	    private LocalDate businessDay(LocalDate date) {
710	        while (isNonBusinessDay(date)) {
711	            date = date.plusDays(1);
712	        }
