802	    /**
803	     * Rejects a create request that would re-register an existing household member unless it declares
804	     * the shared household with {@code sharesHousehold}. The household is keyed on
805	     * {@code (lastName, postcode)} through the deterministic {@link #householdId(Owner)}, so an existing
806	     * owner with the same last name and postcode is a member of the same household. A new owner that
807	     * matches an existing member of that household on its <em>canonical telephone</em> (see
808	     * {@link TelephoneNormalizer#canonicalize(String)}) is a household duplicate and is rejected with a
809	     * 409 (via {@link DuplicateOwnerIdentityException}). A member carrying a <em>different</em> telephone
810	     * is a distinct person in the same household: it is allowed and surfaced instead as a soft
811	     * {@code possibleDuplicate} (see {@link #possibleDuplicateOf(Owner)}), which is what lets a household
812	     * hold more than one owner. Setting {@code sharesHousehold} bypasses this block, so the owner is
813	     * created as a declared household member. Owners without a {@code householdId} (e.g. no postcode)
814	     * have no household to collide with and are always allowed.
815	     *
816	     * @param owner the fully-populated owner being created (household id set, telephone normalized)
817	     * @param sharesHousehold whether the request declared it shares an existing household
818	     * @throws DuplicateOwnerIdentityException if a household member with the same telephone exists and it was not declared
819	     */
820	    private void rejectHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
821	        if (sharesHousehold) {
822	            return;
823	        }
824	        String household = owner.getHouseholdId();
825	        if (household == null) {
826	            return;
827	        }
828	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
829	        boolean sameTelephoneMember = this.clinicService.findAllOwners().stream()
830	            .filter(existing -> !existing.isDeleted())
831	            .filter(existing -> household.equals(existing.getHouseholdId()))
832	            .anyMatch(existing -> java.util.Objects.equals(telephone,
833	                telephoneNormalizer.canonicalize(existing.getTelephone())));
