858	        return this.clinicService.findAllOwners().stream()
859	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
860	                && owner.getPostcode().equals(existing.getPostcode())
861	                && !java.util.Objects.equals(telephone, telephoneNormalizer.canonicalize(existing.getTelephone())))
862	            .map(Owner::getId)
863	            .filter(java.util.Objects::nonNull)
864	            .findFirst()
865	            .orElse(null);
