979	    private int householdSize(Owner owner) {
980	        if (owner.getHouseholdId() == null) {
981	            return 1;
982	        }
983	        return householdMembers(owner).size();
984	    }
985	
986	    /**
987	     * The existing owners that make up the given owner's household: those sharing its
988	     * {@code householdId} (see {@link #householdId(Owner)}). An owner with no {@code householdId}
989	     * (e.g. no postcode) belongs to no shared household, so the result is empty. Whether the owner
990	     * itself appears depends on when the scan runs relative to the create's save: a scan taken after
991	     * the owner is persisted (as the {@link #householdSize(Owner) household size} derivation is)
992	     * counts it among its household, while one taken before the save sees only the owners already
993	     * present. Holding the household lookup in one place lets every household-derived value read the
994	     * same set of members.
995	     *
996	     * @param owner the owner whose household members are wanted
997	     * @return the owners sharing the owner's household, or an empty list when it has no household
998	     */
999	    private List<Owner> householdMembers(Owner owner) {
1000	        String household = owner.getHouseholdId();
1001	        if (household == null) {
1002	            return List.of();
1003	        }
1004	        return this.clinicService.findAllOwners().stream()
1005	            .filter(existing -> household.equals(existing.getHouseholdId()))
1006	            .toList();
1007	    }
1008	
1009	    private String householdId(Owner owner) {
1010	        String postcode = owner.getPostcode();
1011	        if (postcode == null || postcode.isBlank()) {
1012	            return null;
1013	        }
1014	        String key = canonicalizeHousehold(owner.getLastName()) + HOUSEHOLD_KEY_DELIMITER + postcode;
1015	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
1016	    }
1017	
1018	    /**
1019	     * Number of leading hex characters of the household hash retained as the shared
1020	     * {@code householdId}.
1021	     */
1022	    private static final int HOUSEHOLD_ID_LENGTH = 12;
1023	
1024	    /**
1025	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
1026	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
1027	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
1028	     * so every such identifier is produced by the same algorithm and differs only in the value it
1029	     * hashes and the number of hex characters it keeps.
1030	     *
1031	     * @param input the value to hash
1032	     * @param length the number of leading hex characters to keep
1033	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
1034	     */
1035	    private String hashPrefix(String input, int length) {
1036	        try {
1037	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
1038	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
1039	            StringBuilder sb = new StringBuilder(digest.length * 2);
1040	            for (byte b : digest) {
1041	                sb.append(String.format("%02X", b));
1042	            }
1043	            return sb.substring(0, length);
1044	        } catch (java.security.NoSuchAlgorithmException e) {
1045	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
1046	        }
1047	    }
1048	}
